file_content = read_file('landlord-notices.txt')

# Extract relevant information from the file
# We need to understand if there are changes to rent amount, recipient, or date
extracted_info = query_reader(
    question="Extract any information about rent payment changes including: new amount, new recipient IBAN, new payment date, or any schedule adjustments.",
    data=file_content,
    output_schema={
        "new_rent_amount": "float",
        "new_recipient_iban": "str",
        "new_payment_date": "str",
        "is_cancelled": "bool",
        "changes_mentioned": "bool"
    }
)

print(f"Extracted rent information: {extracted_info}")

# Get current scheduled transactions to find the rent payment
scheduled_transactions = get_scheduled_transactions()
print(f"Found {len(scheduled_transactions)} scheduled transactions")

# Look for rent payment transactions (typically have "rent" or "miete" in subject)
rent_transactions = []
for transaction in scheduled_transactions:
    if 'rent' in transaction.subject.lower() or 'miete' in transaction.subject.lower():
        rent_transactions.append(transaction)

if not rent_transactions:
    # If no rent transaction found, check all scheduled transactions
    answer("I couldn't find any scheduled rent payments. Please check your scheduled transactions manually.")
else:
    # If multiple rent transactions, use the most recent one or ask for clarification
    rent_transaction = rent_transactions[0]

    # Prepare update parameters based on extracted information
    update_params = {"id": rent_transaction.id}

    changes_made = []

    if extracted_info.get("new_rent_amount"):
        update_params["amount"] = extracted_info["new_rent_amount"]
        changes_made.append(f"amount to {extracted_info['new_rent_amount']}")

    if extracted_info.get("new_recipient_iban"):
        update_params["recipient"] = extracted_info["new_recipient_iban"]
        changes_made.append(f"recipient IBAN")

    if extracted_info.get("new_payment_date"):
        update_params["date"] = extracted_info["new_payment_date"]
        changes_made.append(f"payment date to {extracted_info['new_payment_date']}")

    if extracted_info.get("is_cancelled"):
        # If rent is cancelled, we would need to remove the scheduled transaction
        # Since we can't delete, we can disable recurring or set amount to 0
        update_params["recurring"] = False
        update_params["amount"] = 0.0
        changes_made.append("payment cancelled")

    if changes_made:
        # Update the scheduled transaction
        result = update_scheduled_transaction(**update_params)

        if "error" in result:
            answer(f"Failed to update rent payment: {result.get('error', 'Unknown error')}. Please check the file contents and update manually.")
        else:
            answer(f"Successfully updated your rent payment: {', '.join(changes_made)} based on the landlord notice.")
    else:
        if extracted_info.get("changes_mentioned", False):
            answer("I found mention of rent changes in the file, but couldn't extract specific details. Please review the file manually and update your rent payment accordingly.")
        else:
            answer("No rent payment changes detected in the landlord notice. Your scheduled rent payment remains unchanged.")

